import{pubertyFigure,cycleFigure,hormoneGraph,ivfFigure}from './repro-figures.js?v=20261023-physicscomplete01';
export const reproFilms={
 'repro-puberty':{title:'Hormone sources and reproductive development',steps:['Reproductive glands produce chemical hormone signals.','Ovaries produce oestrogen, involved in puberty-related development.','Testes produce testosterone, supporting sperm production and secondary sex characteristics.','Blood carries signals to suitable targets; development varies between individuals.'],duration:12,note:'Two separate source/action pathways, not one person with both displayed gland systems. Diamond tracers are hormone signals, not gametes. Scale, speed and timing are symbolic; puberty development is not a fixed movie schedule.',render:p=>pubertyFigure({progress:p})},
 'repro-cycle':{title:'Ovary and uterus: a linked cycle',steps:['Menstruation: the uterus lining is shed in this no-pregnancy example.','FSH supports egg maturation; oestrogen supports lining rebuilding.','LH stimulates egg release from the ovary: ovulation.','Progesterone supports lining maintenance later in the cycle.'],duration:16,note:'Both-tier basic roles. This illustrative28-day-style sequence is not a personal fertility calendar; real timing varies. Ovarian and uterine structures and phases are enlarged and time-compressed. The loop represents a simplified no-pregnancy example; detailed hormone feedback is Higher-only in a separate lesson.',render:p=>cycleFigure({progress:p})},
 'repro-feedback':{title:'Follow the interacting hormone curves',steps:['FSH supports maturation; ovarian oestrogen rises and inhibits further FSH release.','High pre-ovulation oestrogen stimulates an LH surge.','After ovulation, progesterone maintains lining and inhibits FSH and LH.','Without pregnancy, ovarian hormone levels fall; lining support and inhibition decrease.'],duration:16,note:'Higher-only original relative-unit curves with a moving time cursor. Units are illustrative, not clinical hormone concentrations or comparable hormone potencies. Peaks show a teaching example rather than an individual prediction. The known hormonal mechanisms are taught alongside graph interpretation; a curve alone is not proof of causation.',render:p=>hormoneGraph({progress:p})},
 'repro-ivf':{title:'IVF: from stimulation to embryo transfer',steps:['Hormones stimulate several eggs to mature.','Eggs are collected.','Eggs meet sperm in the laboratory; fertilisation may occur.','Fertilised eggs divide and develop into early embryos.','Selected embryo(s) are transferred into the uterus; pregnancy is not guaranteed.'],duration:16,note:'Higher GCSE process summary, not a treatment protocol or dosing simulation. Shapes/counts/time are symbolic. AQA describes one or two embryos; current practice commonly favours single-embryo transfer to reduce multiple-birth risk. The film shows a possible pathway and does not imply every egg fertilises or every embryo implants.',render:p=>ivfFigure({progress:p})}
};
